{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Services — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfa;--card:#fff;--muted:#6b6b6b;--accent:#6aa84f;--accent-2:#3b7bbf;--glass:rgba(255,255,255,0.7);font-family:Inter,system-ui,Segoe UI,Roboto,"Helvetica Neue",Arial}
    *{box-sizing:border-box}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#f3f6f4);color:#222;line-height:1.45}
    header{backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(0,0,0,0.04)}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:16px;padding:14px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700;font-size:18px}
    nav a{color:#333;text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a:hover{background:rgba(0,0,0,0.04)}
    .spacer{flex:1}
    .container{max-width:1100px;margin:36px auto;padding:0 20px}

    /* hero */
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center;background:linear-gradient(180deg,rgba(234,247,239,0.6),transparent);padding:36px;border-radius:14px}
    .hero h1{margin:0;font-size:28px}
    .hero p{margin:6px 0;color:var(--muted)}
    .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(20,30,30,0.04);border:1px solid rgba(0,0,0,0.03)}
    .card h3{margin:0 0 8px 0}
    .muted{color:var(--muted);font-size:14px}

    /* pattern */
    .pattern-wrap{position:fixed;right:0;top:20vh;opacity:0.06;pointer-events:none}
    svg.pattern{width:320px;height:320px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 480ms var(--ease, cubic-bezier(.2,.9,.3,1)),transform 480ms var(--ease, cubic-bezier(.2,.9,.3,1))}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){
      .reveal{transition:none;opacity:1;transform:none}
    }

    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(6,10,8,0.45);display:none;align-items:center;justify-content:center;z-index:60}
    .modal{background:var(--card);padding:20px;border-radius:12px;width:min(720px,96vw);max-height:90vh;overflow:auto}
    .modal header{display:flex;justify-content:space-between;align-items:center}
    .btn{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none}
    .btn-muted{background:#eee;color:#333}
    .small{font-size:13px}

    footer{max-width:1100px;margin:36px auto;padding:14px 20px;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">
        <div class="logo">HM</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div class="small muted">Holistic & integrative support in {{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav class="spacer" aria-label="Main navigation">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="approach.html">How we work</a>
        <a href="conditions.html">Conditions</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div style="display:flex;gap:10px;align-items:center">
        <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button id="tryBtn" class="btn-muted">Try a short exercise</button>
      </div>
    </div>
  </header>

  <div class="pattern-wrap" aria-hidden="true">
    <!-- unique inline SVG pattern -->
    <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" role="img" aria-hidden="true">
      <defs>
        <linearGradient id="g1" x1="0" x2="1">
          <stop offset="0" stop-color="#a8e6a1"/>
          <stop offset="1" stop-color="#7fb3d5"/>
        </linearGradient>
        <pattern id="p1" width="20" height="20" patternUnits="userSpaceOnUse">
          <rect width="10" height="10" fill="rgba(255,255,255,0.02)" />
          <circle cx="15" cy="5" r="2" fill="url(#g1)" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#p1)" rx="18"/>
    </svg>
  </div>

  <main class="container">
    <section class="hero reveal" id="overview">
      <h1>Practical paths for resilient, everyday wellbeing</h1>
      <p>A boutique blend of evidence-informed therapies, nutritional perspectives, and mindful habit design — offered in single sessions, focused packages, and guided add-ons.</p>
      <div style="display:flex;gap:12px;margin-top:14px">
        <a class="btn" href="book.html">Begin a consult</a>
        <button id="tryInline" class="btn-muted">Try a quick breath</button>
      </div>
    </section>

    <!-- Services grid -->
    <section class="reveal" id="offerings" style="margin-top:22px">
      <div style="display:flex;justify-content:space-between;align-items:end">
        <h2 style="margin:0">Offerings & add-ons</h2>
        <div class="small muted">Flexible choices: single visits, 6-week cycles, and at-home add-ons</div>
      </div>
      <div class="cards" style="margin-top:12px">
        <div class="card">
          <h3>Integrative Visit</h3>
          <div class="muted">60–75 minutes</div>
          <p class="small">A comprehensive conversation that blends lab review, lifestyle mapping, and an individualized initial plan.</p>
          <div style="margin-top:10px;display:flex;gap:8px">
            <a class="btn" href="book.html">Schedule</a>
            <a class="btn-muted" href="approach.html">See process</a>
          </div>
        </div>
        <div class="card">
          <h3>Focused Follow-up</h3>
          <div class="muted">30 minutes</div>
          <p class="small">Targeted check-ins for adapting plans, medications, or troubleshooting sleep and mood patterns.</p>
          <div style="margin-top:10px;display:flex;gap:8px">
            <a class="btn" href="book.html">Book follow-up</a>
            <a class="btn-muted" href="pricing.html">Pricing</a>
          </div>
        </div>
        <div class="card">
          <h3>At-home Add-on: Guided Cycle</h3>
          <div class="muted">4-week guided curriculum</div>
          <p class="small">A lightweight mix of weekly micro-lessons, journaling prompts, and a short audio practice — meant to layer onto clinical care.</p>
          <div style="margin-top:10px;display:flex;gap:8px">
            <a class="btn" href="pricing.html">Add to care</a>
            <button class="btn-muted" id="openCycleInfo">Details</button>
          </div>
        </div>
      </div>
    </section>

    <!-- Pillars / why section -->
    <section class="reveal" id="pillars" style="margin-top:28px">
      <h2>How we shape support</h2>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px">
        <div class="card"><h3>Context-first thinking</h3><p class="small muted">Symptoms are signals. We map context: sleep, stress, digestion, movement, and relationships.</p></div>
        <div class="card"><h3>Actionable experiments</h3><p class="small muted">Small, trackable changes replace overwhelm with clarity.</p></div>
        <div class="card"><h3>Respect for pace</h3><p class="small muted">Change is cumulative — plans that fit your life, not the other way around.</p></div>
      </div>
    </section>

    <!-- CTA -->
    <section class="reveal" id="cta" style="margin-top:28px;display:flex;align-items:center;gap:16px;justify-content:space-between">
      <div>
        <h3 style="margin:0">Ready to pick a first step?</h3>
        <p class="small muted" style="margin:6px 0">Choose single visits or pair them with a guided cycle for more support between sessions.</p>
      </div>
      <div style="display:flex;gap:10px">
        <a class="btn" href="book.html">Reserve a time</a>
        <a class="btn-muted" href="contact.html">Ask a question</a>
      </div>
    </section>

  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;max-width:1100px;margin:0 auto">
      <div class="muted">© <span id="year"></span> {{BUSINESS_NAME}} — <span class="small">{{CITY}}, {{STATE}}</span></div>
      <div class="small muted">Phone: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <header>
        <div>
          <h2 id="modalTitle">Try a brief guided practice</h2>
          <div class="small muted">Choose breathing, journaling, or intention-setting</div>
        </div>
        <div>
          <button id="modalClose" class="btn-muted">Close</button>
        </div>
      </header>
      <hr>
      <div style="display:grid;grid-template-columns:1fr 2fr;gap:12px">
        <nav style="display:flex;flex-direction:column;gap:8px">
          <button class="btn-muted small" data-mode="breath">Breathing</button>
          <button class="btn-muted small" data-mode="journal">Journaling</button>
          <button class="btn-muted small" data-mode="intent">Intention</button>
        </nav>
        <div id="modalBody">
          <div id="breathUI" style="display:none">
            <p class="muted">A simple 4-4-6 breathing for quieting the nervous system.</p>
            <div style="display:flex;align-items:center;gap:12px;margin-top:8px">
              <button id="startBreath" class="btn">Start</button>
              <button id="stopBreath" class="btn-muted">Stop</button>
              <div class="small muted">Cycles remaining: <span id="breathCount">3</span></div>
            </div>
            <div id="breathCircle" aria-hidden="true" style="margin-top:16px;width:120px;height:120px;border-radius:50%;background:linear-gradient(180deg,#e6f7e8,#f3fbff);display:flex;align-items:center;justify-content:center;font-weight:700;color:#2b6a4a">Breathe</div>
          </div>

          <div id="journalUI" style="display:none">
            <p class="muted">A brief prompt to collect what’s active for you. No pressure to be perfect.</p>
            <textarea id="journalText" rows="6" style="width:100%;margin-top:8px;padding:10px;border-radius:8px;border:1px solid #e6e6e6" placeholder="What matters most today? What would you like to notice?">
            </textarea>
            <div style="display:flex;gap:8px;margin-top:8px">
              <button id="saveJournal" class="btn">Save note</button>
              <button id="clearJournal" class="btn-muted">Clear</button>
              <div id="journalSaved" class="small muted" style="display:none">Saved to local notes</div>
            </div>
          </div>

          <div id="intentUI" style="display:none">
            <p class="muted">Set a short intention you can return to through the day.</p>
            <input id="intentInput" placeholder="A single-line intention" style="width:100%;padding:10px;border-radius:8px;border:1px solid #e6e6e6">
            <div style="display:flex;gap:8px;margin-top:8px">
              <button id="saveIntent" class="btn">Set intention</button>
              <button id="clearIntent" class="btn-muted">Clear</button>
              <div id="intentSaved" class="small muted" style="display:none">Intent active</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // basic utilities
    document.getElementById('year').textContent = new Date().getFullYear();

    // REVEAL ON SCROLL
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
      if(prefersReduced){
        document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));
        return;
      }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting) { e.target.classList.add('visible'); io.unobserve(e.target); }
        });
      },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
    })();

    // Modal + Guided exercise
    const modal = document.getElementById('modal');
    const modalClose = document.getElementById('modalClose');
    const tryBtn = document.getElementById('tryBtn');
    const tryInline = document.getElementById('tryInline');
    const buttons = Array.from(document.querySelectorAll('[data-mode]'));
    const breathUI = document.getElementById('breathUI');
    const journalUI = document.getElementById('journalUI');
    const intentUI = document.getElementById('intentUI');

    function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
    function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.body.style.overflow=''; stopBreathing(); }

    tryBtn.addEventListener('click', openModal);
    tryInline.addEventListener('click', ()=>{ openModal(); activateMode('breath'); });
    modalClose.addEventListener('click', closeModal);
    modal.addEventListener('click', (e)=>{ if(e.target===modal) closeModal(); });

    buttons.forEach(b=>b.addEventListener('click', (e)=> activateMode(e.currentTarget.dataset.mode)));

    function activateMode(mode){ breathUI.style.display='none'; journalUI.style.display='none'; intentUI.style.display='none';
      if(mode==='breath') breathUI.style.display='block';
      if(mode==='journal') journalUI.style.display='block';
      if(mode==='intent') intentUI.style.display='block';
    }

    // Breathing exercise (4-4-6 cycles)
    let breathTimer = null; let breathCycles = 3; const breathCountEl = document.getElementById('breathCount');
    const breathCircle = document.getElementById('breathCircle');
    document.getElementById('startBreath').addEventListener('click', ()=>startBreathing(3));
    document.getElementById('stopBreath').addEventListener('click', stopBreathing);

    function startBreathing(cycles){ stopBreathing(); breathCycles = cycles; breathCountEl.textContent = breathCycles; let phase=0; // 0 inhale,1 hold,2 exhale
      let step=0; breathCircle.textContent='Inhale'; breathCircle.style.transition='transform 4s ease-in-out';
      breathTimer = setInterval(()=>{
        if(phase===0){ // inhale 4s
          breathCircle.textContent='Hold'; breathCircle.style.transform='scale(1.15)'; phase=1; setTimeout(()=>{},4000);
        } else if(phase===1){ // hold 4s
          breathCircle.textContent='Exhale'; breathCircle.style.transform='scale(0.9)'; phase=2; setTimeout(()=>{},4000);
        } else { // exhale 6s and complete one cycle
          breathCycles -=1; breathCountEl.textContent = breathCycles; breathCircle.textContent='Inhale'; breathCircle.style.transform='scale(1)'; phase=0; if(breathCycles<=0){ stopBreathing(); }
        }
      },14000); // full cycle ~14s
    }
    function stopBreathing(){ if(breathTimer){ clearInterval(breathTimer); breathTimer=null; breathCircle.textContent='Breathe'; breathCircle.style.transform='none'; breathCountEl.textContent=3; }}

    // Journaling (local save)
    const journalText = document.getElementById('journalText');
    const saveJournal = document.getElementById('saveJournal');
    const clearJournal = document.getElementById('clearJournal');
    const journalSaved = document.getElementById('journalSaved');
    saveJournal.addEventListener('click', ()=>{
      const t = journalText.value.trim(); if(!t) return; let notes = JSON.parse(localStorage.getItem('hm_notes')||'[]'); notes.push({text:t,ts:Date.now()}); localStorage.setItem('hm_notes',JSON.stringify(notes)); journalSaved.style.display='inline'; setTimeout(()=>journalSaved.style.display='none',2200);
    });
    clearJournal.addEventListener('click', ()=>{ journalText.value=''; });

    // Intention
    const intentInput = document.getElementById('intentInput');
    const saveIntent = document.getElementById('saveIntent');
    const clearIntent = document.getElementById('clearIntent');
    const intentSaved = document.getElementById('intentSaved');
    saveIntent.addEventListener('click', ()=>{ const v = intentInput.value.trim(); if(!v) return; localStorage.setItem('hm_intent', v); intentSaved.style.display='inline'; setTimeout(()=>intentSaved.style.display='none',2200); });
    clearIntent.addEventListener('click', ()=>{ localStorage.removeItem('hm_intent'); intentInput.value=''; intentSaved.style.display='none'; });

    // small detail: keyboard escape closes
    window.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeModal(); });
  </script>
</body>
</html>"} 
